import { performance, PerformanceObserver } from "node:perf_hooks";
function main(): void {
  const o = new PerformanceObserver((list, observer) => { console.log("once", list.getEntries().length); observer.disconnect(); });
  o.observe({ entryTypes: ["mark"] });
  performance.mark("y");
  setTimeout(() => performance.mark("z"), 20);
  setTimeout(() => console.log("after"), 40);
}
